visual.source:
flowchart TB
  subgraph P1["前半: 考え方"]
    EB@{ svc: "AWS Elastic Beanstalk", label: "Beanstalk<br/>in-place・blue/green<br/>Immutable・canary" }
  end
  subgraph P2["後半: 当てはめ"]
    CD@{ svc: "AWS CodeDeploy", label: "CodeDeploy" }
    EC2@{ svc: "Amazon EC2", label: "EC2: インスタンス" }
    ECS@{ svc: "Amazon ECS", label: "ECS: コンテナ" }
    L@{ svc: "AWS Lambda", label: "Lambda: 関数" }
  end
  EB -- "同じ考え方で" --> CD
  CD --> EC2
  CD --> ECS
  CD --> L

flowchart TB
  EB@{ svc: "AWS Elastic Beanstalk", label: "Beanstalk<br/>Immutable ポリシー" }
  OLD@{ svc: "Amazon EC2", label: "古い版のインスタンス<br/>横で動き続ける" }
  NEW@{ svc: "Amazon EC2 Auto Scaling", label: "別の Auto Scaling group<br/>新しい版の一式" }
  BAD["health check 不合格<br/>新しい方だけ終了"]
  EB -. "手を付けない" .-> OLD
  EB -- "新しい一式を起動" --> NEW
  NEW -. "不合格のとき" .-> BAD

flowchart TB
  CD@{ svc: "AWS CodeDeploy", label: "CodeDeploy" }
  EC2@{ svc: "Amazon EC2", label: "EC2/On-Premises<br/>CodeDeploy agent<br/>外向き HTTPS 443" }
  ECS@{ svc: "Amazon ECS", label: "ECS" }
  L@{ svc: "AWS Lambda", label: "Lambda" }
  SSM@{ svc: "AWS Systems Manager", label: "Systems Manager" }
  CD -- "agent が要る" --> EC2
  CD -- "agent は要らない" --> ECS
  CD -- "agent は要らない" --> L
  SSM -- "一度か日程で導入" --> EC2

flowchart TB
  CD@{ svc: "AWS CodeDeploy", label: "CodeDeploy<br/>deployment configuration" }
  subgraph G["デプロイ中の EC2"]
    K@{ svc: "Amazon EC2", label: "使える状態で残す<br/>minimum healthy hosts（数か割合）" }
    U@{ svc: "Amazon EC2", label: "新しい版に更新中" }
  end
  D["指定しないときの既定<br/>CodeDeployDefault.OneAtATime"]
  CD -- "残す数か割合" --> K
  CD -- "新しい版を入れる" --> U
  CD -. "既定" .-> D

flowchart TB
  CD@{ svc: "AWS CodeDeploy", label: "CodeDeploy<br/>移し方を決める" }
  LB@{ svc: "Elastic Load Balancing", label: "ALB か NLB" }
  O@{ svc: "Amazon ECS", label: "original task set<br/>古い版" }
  R@{ svc: "Amazon ECS", label: "replacement task set<br/>新しい版" }
  CD -- "本番トラフィックを移す" --> LB
  LB -. "移す前" .-> O
  LB -- "移した後" --> R
